/**
 * Copies the current marketing notes into src/content/internal/marketing-docs.ts
 * so /interno-64a0f7d0 can show them.
 *
 * The markdown lives in marketing/ and .agents/, outside what the deployed
 * server bundle can read at runtime, so the page imports a generated module
 * instead. Run `npm run docs:internal` after editing any of these notes, and
 * commit the generated file with them.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(__dirname, "..");

// Order is the tab order on the page: what governs today first.
const DOCS: { key: string; label: string; file: string }[] = [
  { key: "panorama", label: "Panorama", file: "marketing/notas/02-panorama.md" },
  { key: "dia-por-dia", label: "Día por día", file: "marketing/notas/03-dia-por-dia.md" },
  { key: "medicion", label: "Medición", file: "marketing/notas/05-medicion.md" },
  { key: "adquisicion", label: "Prospección", file: "marketing/notas/02b-adquisicion.md" },
  { key: "mensajes-venta", label: "Mensajes", file: "marketing/ventas/mensajes.md" },
  { key: "respuestas", label: "Respuestas", file: "marketing/ventas/respuestas.md" },
  { key: "plan-2026-11", label: "Plan y oferta", file: "marketing/notas/01-plan.md" },
  { key: "contenido-2026-11", label: "Contenido 90 días", file: "marketing/notas/04-contenido.md" },
  { key: "backlog", label: "Banco de ideas", file: "marketing/contenido/reels/backlog.md" },
  { key: "historias", label: "Historias y estados", file: "marketing/contenido/historias/README.md" },
  { key: "produccion-2026-11", label: "Producción", file: "marketing/contenido/reels/PRODUCCION.md" },
  { key: "matriz", label: "Matriz", file: "marketing/investigacion/matriz-2026-11.md" },
  { key: "competencia", label: "Competencia", file: "marketing/investigacion/competencia-2026-11.md" },
  { key: "voz", label: "Voz del cliente", file: "marketing/investigacion/voz-del-cliente.md" },
  { key: "contexto", label: "Contexto de producto", file: ".agents/product-marketing.md" },
  { key: "indice", label: "Qué manda", file: "marketing/CLAUDE.md" },
  { key: "archivo", label: "Archivo", file: "marketing/notas/10-archivo.md" },
];

// Every reel package and DM resource gets its own tab, newest reel first.
function listMd(dir: string, labelFor: (name: string) => string, only: RegExp = /./) {
  try {
    return readdirSync(join(root, dir))
      .filter((name) => name.endsWith(".md") && !name.startsWith("_") && only.test(name))
      .sort()
      .reverse()
      .map((name) => ({ key: `${dir}/${name}`, label: labelFor(name), file: `${dir}/${name}` }));
  } catch {
    return [];
  }
}
DOCS.splice(
  9,
  0,
  ...listMd("marketing/contenido/reels", (n) => `Reel ${n.slice(0, 2)}`, /^\d/),
  ...listMd("marketing/contenido/recursos", (n) => `Recurso: ${n.replace(/\.md$/, "")}`),
);

const entries = DOCS.flatMap((doc) => {
  let source: string;
  try {
    source = readFileSync(join(root, doc.file), "utf8");
  } catch {
    console.warn(`skip ${doc.file} (not found)`);
    return [];
  }
  return [`  {\n    key: ${JSON.stringify(doc.key)},\n    label: ${JSON.stringify(doc.label)},\n    source: ${JSON.stringify(source)},\n  },`];
});

const out = `// GENERATED by scripts/sync-internal-docs.ts — do not edit by hand.
// Source: the marketing notes listed in that script. Run \`npm run docs:internal\`.

export const marketingDocs: { key: string; label: string; source: string }[] = [
${entries.join("\n")}
];
`;

writeFileSync(join(root, "src/content/internal/marketing-docs.ts"), out);
console.log(`wrote ${entries.length} docs`);
